#pragma once
#include <stdint.h>

/* Version 1 records generated by rplimportgen and elf2rpl. */
typedef struct WUTModuleImport
{
   uint32_t *target;
   const char *exportName;
   int32_t addend;
   uint32_t kind; /* 0: function address, 1: data address, 2: TLS descriptor */
} WUTModuleImport;

typedef struct WUTModuleImportTable
{
   uint32_t count;
   WUTModuleImport imports[];
} WUTModuleImportTable;

int
__wut_bind_imports_v1(const WUTModuleImport *imports, uint32_t count);
